import '../models/social_models.dart';
import '../services/social_service.dart';
class SocialRepository { final SocialService _s=SocialService(); Future<List<SocialPost>> feed()=>_s.feed(); Stream<List<SocialPost>> feedStream()=>_s.feedStream(); Future<String> createPost(String b,{String? mediaUrl,String mediaType='none',String visibility='public'})=>_s.createPost(b,mediaUrl:mediaUrl,mediaType:mediaType,visibility:visibility); Future<bool> likePost(String id)=>_s.likePost(id); Future<void> viewPost(String id,{int watchMs=0})=>_s.viewPost(id,watchMs:watchMs); Future<List<SocialComment>> comments(String id)=>_s.comments(id); Future<void> addComment(String id,String b,{String? parentId})=>_s.addComment(id,b,parentId:parentId); Future<bool> likeComment(String id)=>_s.likeComment(id); Future<String> createStory(String u,{String caption='',String mediaType='image',String visibility='followers'})=>_s.createStory(u,caption:caption,mediaType:mediaType,visibility:visibility); Future<List<SocialStory>> stories()=>_s.stories(); Future<void> viewStory(String id)=>_s.viewStory(id); Future<String> createReel(String u,{String caption='',String? thumbnailUrl,int durationMs=0,String visibility='public'})=>_s.createReel(u,caption:caption,thumbnailUrl:thumbnailUrl,durationMs:durationMs,visibility:visibility); Future<List<SocialReel>> reels()=>_s.reels(); Future<bool> likeReel(String id)=>_s.likeReel(id); Future<List<Map<String,dynamic>>> reelComments(String id)=>_s.reelComments(id); Future<void> addReelComment(String id,String body,{String? parentId})=>_s.addReelComment(id,body,parentId:parentId); Future<void> viewReel(String id,{required int watchMs,required bool completed,int rewatch=0})=>_s.viewReel(id,watchMs:watchMs,completed:completed,rewatch:rewatch); Future<List<Map<String,dynamic>>> search(String q)=>_s.search(q); Future<List<CreatorMetric>> analytics({int days=30})=>_s.analytics(days:days); Future<void> report({required String targetType,required String targetId,required String reason,String details=''})=>_s.report(targetType:targetType,targetId:targetId,reason:reason,details:details); }
